'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const M=require('../js/modules/character-sheet-model'),R=require('../js/modules/character-rules'),F=require('../js/modules/character-class-feature-choices');
const character=build=>M.normalize({hpMax:20,abilities:{str:14,dex:14,con:14,int:16,wis:14,cha:18},build:{classId:'fighter',scoreMode:'base',edition:'2014',...build}});
test('racial once-per-long-rest spells all receive independent counters at their actual unlock levels',()=>{
 let checked=0;
 for(const [race,row]of Object.entries(R.races))for(const [feature,options]of [['raceFeature',row.optionChoices||{}]])for(const option of [null,...Object.keys(options)]){
  const d=character({race,edition:row.edition||'2014',raceAbility:'cha',...(option?{[feature]:option}:{})});
  for(const level of [1,2,3,4,5,20]){
   const profile=R.profile(d.build,level),resources=F.classResources(d,{level,mods:{cha:4}}).filter(r=>r.id.startsWith('origin-'));
   const expected=(profile?.spells||[]).filter(s=>s.level<=level&&/^(?:once|[1-9]\d?) per long rest(?:;|$)/i.test(s.usage));
   assert.equal(resources.length,expected.length,race+' '+option+' '+level);
   for(const spell of expected){const resource=resources.find(r=>r.name===spell.name);assert.ok(resource,spell.name);assert.equal(resource.remaining,1);assert.deepEqual(resource.resets,['long']);assert.ok(!resource.description.includes('CHOICE'));checked++;}
  }
 }
 assert.ok(checked>100,'exercise ordinary species as well as selected legacies');
});
const SpeciesResources=require('../js/modules/character-species-resources'),SpeciesResourceFacts=require('../js/modules/character-species-resource-data');
test('reviewed species counters retain 34 checked feature identities without source entries or permanent transformation claims',()=>{
 assert.equal(Object.keys(SpeciesResourceFacts.species).length,22);assert.equal(Object.values(SpeciesResourceFacts.species).flatMap(row=>row.resources).length,34);assert.match(SpeciesResourceFacts.sourceSha256,/^[a-f0-9]{64}$/);
 for(const [race,definition]of Object.entries(SpeciesResourceFacts.species)){assert.ok(R.races[race]);assert.equal(new Set(definition.resources.map(row=>row.id)).size,definition.resources.length);for(const row of definition.resources){assert.equal(row.reference.feature,row.name);assert.ok(row.reference.source);assert.ok(!('entries' in row));assert.ok(row.level>=1&&row.level<=20);for(const option of Object.keys(row.optionDetails||{}))assert.ok(R.races[race].optionChoices[option]);}}
});
test('species counters unlock from total character level, scale PB independently of class allocation and keep source choices separate',()=>{
 for(const [race,definition]of Object.entries(SpeciesResourceFacts.species))for(const level of [1,2,3,4,5,6,9,13,17,20]){
  const profile=R.races[race],d=character({race,edition:profile.edition||'2014',raceFeature:Object.keys(profile.optionChoices||{})[0]||'',raceAbility:'wis',dragon:'red'});d.adobe={classLevels:[{classId:'fighter',level:1},{classId:'wizard',level:20}]};const before=JSON.stringify(d),rows=M.derive(d,level).classResources.filter(row=>row.speciesResource);assert.equal(rows.length,definition.resources.filter(row=>row.level<=level).length,race+' '+level);
  for(const row of rows){const fact=definition.resources.find(f=>f.id===row.featureId);assert.equal(row.max,fact.uses==='pb'?Math.ceil(level/4)+1:fact.uses);assert.equal(row.used,0);assert.equal(row.level,level);assert.equal(row.useDisabled,false,race+' '+row.name);assert.doesNotMatch(row.description,/\{[a-zA-Z]+\}/);}
  assert.equal(JSON.stringify(d),before);
 }
 const d=character({edition:'2014',race:'orc-2024'});assert.equal(M.derive(d,20).classResources.some(row=>row.speciesResource),false);
});
test('species use ledgers are independent, retain spends through switching/save and recover using their actual source edition',()=>{
 const d=character({race:'orc-2024',edition:'2024'});let rows=M.derive(d,5).classResources.filter(row=>row.speciesResource);for(const row of rows)assert.equal(F.changeClassResource(d,row.id,1,{level:5}),true);F.resetClassResources(d,'short',{level:5});rows=M.derive(d,5).classResources.filter(row=>row.speciesResource);assert.equal(rows.find(row=>row.featureId==='rush').remaining,3);assert.equal(rows.find(row=>row.featureId==='endurance').remaining,0);
 d.build={...d.build,race:'orc-mpmm',edition:'2014'};assert.equal(F.changeClassResource(d,'species-rush',1,{level:5}),true);F.resetClassResources(d,'short',{level:5});assert.equal(M.derive(d,5).classResources.find(row=>row.id==='species-rush').remaining,2);d.build.race='human';F.resetClassResources(d,'long',{level:5});d.build.race='orc-mpmm';assert.equal(M.derive(JSON.parse(JSON.stringify(d)),5).classResources.find(row=>row.id==='species-rush').remaining,3);d.build.race='orc-2024';d.build.edition='2024';assert.equal(M.derive(d,5).classResources.find(row=>row.id==='species-endurance').remaining,1);
 d.build={...d.build,race:'ravenite-dragonborn-egw',edition:'2014'};rows=M.derive(d,5).classResources.filter(row=>row.speciesResource);assert.equal(rows.length,2);for(const row of rows)assert.equal(F.changeClassResource(d,row.id,1,{level:5}),true);assert.equal(F.changeClassResource(d,'species-breath',1,{level:5}),false);F.resetClassResources(d,'short',{level:5});assert.ok(M.derive(d,5).classResources.filter(row=>row.speciesResource).every(row=>row.remaining===1));
});
test('Fury of the Small atomically enforces its turn limit separately from daily recovery, including another creature’s new turn',()=>{
 const d=character({race:'goblin-mpmm'});assert.equal(F.changeClassResource(d,'species-fury',1,{level:5}),true);assert.equal(F.changeClassResource(d,'species-fury',1,{level:5}),false);assert.equal(SpeciesResources.newTurn(d,'species-fury',{level:5}),true);assert.equal(M.derive(d,5).classResources.find(row=>row.id==='species-fury').remaining,2);assert.equal(F.changeClassResource(d,'species-fury',1,{level:5}),true);F.resetClassResources(d,'turn',{level:5});assert.equal(F.changeClassResource(d,'species-fury',1,{level:5}),true);SpeciesResources.newTurn(d,'species-fury',{level:5});assert.equal(F.changeClassResource(d,'species-fury',1,{level:5}),false,'a turn change cannot restore daily uses');assert.equal(F.changeClassResource(d,'species-fury',-1,{level:5}),true);assert.equal(F.changeClassResource(d,'species-fury',1,{level:5}),true);
});
test('species counters fail closed for malformed spends, refuse full-ledger writes atomically and do not award HP, flight or immunity',()=>{
 const d=character({race:'goblin-mpmm'});d.adobe={classFeatureChoices:Object.fromEntries(Array.from({length:99},(_,i)=>['retained:'+i,['1']]))};let before=JSON.stringify(d);assert.equal(F.changeClassResource(d,'species-fury',1,{level:5}),false);assert.equal(JSON.stringify(d),before);
 const orc=character({race:'orc-2024',edition:'2024'}),key=SpeciesResources.resources(orc,{level:5})[0].key;for(const invalid of [null,true,'0',{},['0','1']]){orc.adobe={classFeatureChoices:{[key]:invalid}};assert.equal(M.derive(orc,5).classResources.find(row=>row.id==='species-rush').remaining,0);assert.equal(F.changeClassResource(orc,'species-rush',1,{level:5}),false);orc.adobe.classFeatureChoices=F.normalize(orc.adobe.classFeatureChoices);assert.equal(M.derive(orc,5).classResources.find(row=>row.id==='species-rush').remaining,0,'normalizing a malformed counter cannot manufacture free uses');F.resetClassResources(orc,'short',{level:5});assert.equal(M.derive(orc,5).classResources.find(row=>row.id==='species-rush').remaining,3);}
 for(const [race,edition,id]of [['orc-2024','2024','species-rush'],['dragonborn-2024','2024','species-flight'],['chromatic-dragonborn-ftd','2014','species-warding']]){const d=character({race,edition,raceFeature:'red',dragon:'red'}),before=M.derive(d,5),vitals=JSON.stringify({hp:d.hpCurrent,temp:d.hpTemp,slots:d.slots});assert.equal(F.changeClassResource(d,id,1,{level:5}),!before.classResources.find(row=>row.id===id).managedActivation);const after=M.derive(d,5);assert.equal(JSON.stringify({hp:d.hpCurrent,temp:d.hpTemp,slots:d.slots}),vitals);assert.equal(after.effects.fly,before.effects.fly);assert.deepEqual(after.effects.immunities,before.effects.immunities);}
});
test('species option counters show only the selected power, gate missing choices and expose Eladrin’s own feature ability',()=>{
 const d=character({race:'goliath-2024',edition:'2024'});assert.equal(M.derive(d,5).classResources.find(row=>row.id==='species-giant-ancestry').useDisabled,true);d.build.raceFeature='constructor';assert.equal(M.derive(d,5).classResources.find(row=>row.id==='species-giant-ancestry').useDisabled,true);d.build.raceFeature='fire';let row=M.derive(d,5).classResources.find(row=>row.id==='species-giant-ancestry');assert.match(row.description,/1d10 Fire/);assert.doesNotMatch(row.description,/1d8 Thunder|reduce that damage/);assert.equal(row.useDisabled,false);
 d.build={...d.build,race:'shifter-mpmm',edition:'2014',raceFeature:'beasthide'};row=M.derive(d,5).classResources.find(row=>row.id==='species-shifting');assert.match(row.description,/6 temporary HP.*1d6.*\+1 AC/);assert.doesNotMatch(row.description,/bite|Swiftstride/);
 d.build={...d.build,race:'eladrin-mpmm',raceFeature:'winter',raceAbility:'wis'};assert.equal(R.profile(d.build,5).featureAbilityChoice,true);row=M.derive(d,5).classResources.find(row=>row.id==='species-fey-step');assert.match(row.description,/DC.*13/);assert.equal(R.evaluate(d,5).raceAbility,'wis');
});
const SpeciesForms=require('../js/modules/character-species-forms');
function speciesForm(race,level=5,extra={}){const d=character({race,edition:R.races[race].edition||'2014',raceFeature:'red',dragon:'red',...extra});d.hpCurrent=10;return {d,level,context:{level,confirmed:true,onStone:true}};}
test('temporary species effects require their source, unlock, action conditions and an atomic use/activation write',()=>{
 assert.equal(Object.keys(SpeciesForms.definitions).length,6);
 for(const race of ['shadar-kai-mpmm','dwarf-2024','goliath-2024','dragonborn-2024','gem-dragonborn-ftd','chromatic-dragonborn-ftd']){
  const {d,context}=speciesForm(race),s=SpeciesForms.state(d,context);assert.equal(s.canActivate,true,race);assert.equal(F.changeClassResource(d,s.resource.id,1,context),false,'a counter edit cannot bypass activation');assert.equal(SpeciesForms.activate(d,{...context,confirmed:false}),false);assert.equal(SpeciesForms.activate(d,context),true);assert.equal(M.derive(d,5).speciesForm.active,true);assert.equal(SpeciesForms.state(d,context).resource.used,1);
  const saved=JSON.parse(JSON.stringify(d));assert.equal(M.derive(saved,5).speciesForm.active,true);SpeciesForms.end(saved,context);assert.equal(M.derive(saved,5).speciesForm.active,false);assert.equal(SpeciesForms.state(saved,context).resource.used,1);assert.equal(SpeciesForms.undo(saved,context),true);assert.equal(SpeciesForms.state(saved,context).resource.used,0);
 }
 const {d,context}=speciesForm('dragonborn-2024',4);assert.equal(SpeciesForms.activate(d,context),false);d.build.edition='2014';assert.equal(SpeciesForms.activate(d,{...context,level:20}),false);
 const full=speciesForm('dwarf-2024');full.d.adobe={classFeatureChoices:Object.fromEntries(Array.from({length:98},(_,i)=>['retained:'+i,['0']]))};const before=JSON.stringify(full.d);assert.equal(SpeciesForms.activate(full.d,full.context),false);assert.equal(JSON.stringify(full.d),before,'Stonecunning needs three ledger keys and cannot spend only part of its activation');
});
test('Shadar-Kai teleport resistance starts at level 3, ends on the actual next turn and never restores teleport uses',()=>{
 const low=speciesForm('shadar-kai-mpmm',2);assert.equal(SpeciesForms.activate(low.d,low.context),true);assert.equal(M.derive(low.d,2).speciesForm.active,false);assert.deepEqual(M.derive(low.d,2).effects.resistances,['Necrotic']);
 const {d,context}=speciesForm('shadar-kai-mpmm');SpeciesForms.activate(d,context);assert.equal(M.derive(d,5).effects.resistances.length,13);F.resetClassResources(d,'turn',{level:5});assert.deepEqual(M.derive(d,5).effects.resistances,['Necrotic']);assert.equal(SpeciesForms.state(d,context).resource.remaining,2);assert.equal(SpeciesForms.activate(d,context),true);F.resetClassResources(d,'long',{level:5});assert.equal(SpeciesForms.state(d,context).rawActive,false);assert.equal(SpeciesForms.state(d,context).resource.remaining,3);
});
test('Stonecunning requires stone at activation and toggles contact without consuming another use or permanently granting a sense',()=>{
 const {d,context}=speciesForm('dwarf-2024');assert.equal(SpeciesForms.activate(d,{...context,onStone:false}),false);assert.equal(SpeciesForms.activate(d,context),true);let r=M.derive(d,5);assert.equal(r.effects.tremorsense,60);assert.ok(r.effects.specialSenses.some(row=>row.name==='Stonecunning'&&/touching stone/.test(row.detail)));SpeciesForms.setStone(d,false,context);r=M.derive(d,5);assert.equal(r.speciesForm.active,true);assert.ok(!r.effects.tremorsense);assert.equal(SpeciesForms.state(d,context).resource.used,1);SpeciesForms.setStone(d,true,context);assert.equal(M.derive(d,5).effects.tremorsense,60);SpeciesForms.end(d,context);assert.ok(!M.derive(d,5).effects.tremorsense);
});
test('Large Form updates real size, walking speed and Powerful Build carrying, grants check Advantage without a flat bonus and restores on End',()=>{
 const {d,context}=speciesForm('goliath-2024'),base=M.derive(d,5),Tool=require('../js/modules/character-tool-checks');SpeciesForms.activate(d,context);let r=M.derive(d,5);assert.equal(r.effects.size,'Large');assert.equal(r.effects.speed-base.effects.speed,10);assert.equal(r.carrying.capacity,base.carrying.capacity*2);assert.equal(r.carrying.effectiveSize,'Huge');const a=Tool.project({name:'Lift (Str)'},base),b=Tool.project({name:'Lift (Str)'},r);assert.equal(b.total,a.total);assert.equal(b.advantageGranted,true);assert.match(Tool.describe(b),/Advantage granted/);assert.deepEqual(r.saves,base.saves);SpeciesForms.end(d,context);r=M.derive(d,5);assert.equal(r.effects.size,base.effects.size);assert.equal(r.effects.speed,base.effects.speed);assert.equal(r.carrying.capacity,base.carrying.capacity);
});
test('Large Form applies walking changes before class flight/swim links, including doubled Psi-Powered Leap',()=>{
 for(const [classId,subclassId,level,flag,multiplier]of [['monk','elements-2024',11,'attunement-active',1],['fighter','psi-warrior-2024',7,'fighter-psi-leap-active',2]]){
  const {d}=speciesForm('goliath-2024',level);d.build.classId=classId;d.adobe={classLevels:[{classId,subclassId,level}],classFeatureChoices:{}};const Sub=require('../js/modules/character-'+classId+'-subclasses'),r=Sub.derive(d,{level});d.adobe.classFeatureChoices[r.key(flag)]=['active'];const base=M.derive(d,level);assert.equal(base.effects.fly,base.effects.speed*multiplier);assert.equal(SpeciesForms.activate(d,{level,confirmed:true}),true);const active=M.derive(d,level);assert.equal(active.effects.speed,base.effects.speed+10);assert.equal(active.effects.fly,active.effects.speed*multiplier);if(classId==='monk')assert.equal(active.effects.swim,active.effects.speed);
 }
});
test('a class size change preserves Totem Bear’s carrying multiplier together with the species’ Powerful Build',()=>{
 const d=character({edition:'2014',race:'goliath-mpmm',classId:'fighter'}),Fighter=require('../js/modules/character-fighter-subclasses'),Barbarian=require('../js/modules/character-barbarian-subclasses');d.adobe={classLevels:[{classId:'fighter',level:3,subclassId:'rune-knight'},{classId:'barbarian',level:6,subclassId:'totem-warrior'}],classFeatureChoices:{}};const f=Fighter.derive(d,{level:9}),b=Barbarian.context(d,{level:9});d.adobe.classFeatureChoices[b.key('aspect-of-the-beast')]=['bear'];const base=M.derive(d,9);assert.equal(base.carrying.capacity,14*15*2*2);d.adobe.classFeatureChoices[f.key('fighter-giants-might-active')]=['active'];d.adobe.classFeatureChoices[f.key('giant-size')]=['large'];const large=M.derive(d,9);assert.equal(large.effects.size,'Large');assert.equal(large.carrying.capacity,14*15*4*2);assert.equal(large.carrying.pushDragLift,large.carrying.capacity*2);
});
test('species flight uses current walking speed with existing penalties and only the stated Incapacitated ending; completed rests expire brief forms without refunding daily uses',()=>{
 for(const race of ['dragonborn-2024','gem-dragonborn-ftd']){const {d,context}=speciesForm(race);SpeciesForms.activate(d,context);let r=M.derive(d,5);assert.equal(r.effects.fly,r.effects.speed);assert.equal(!!r.effects.hover,race==='gem-dragonborn-ftd');d.conditions='Exhaustion 1';r=M.derive(d,5);assert.equal(r.effects.fly,r.effects.speed);F.resetClassResources(d,'short',{level:5});assert.equal(SpeciesForms.state(d,context).active,false);assert.equal(SpeciesForms.state(d,context).resource.used,1);SpeciesForms.undo(d,context);SpeciesForms.activate(d,context);d.conditions='Stunned';SpeciesForms.endInvalid(d,context);assert.equal(SpeciesForms.state(d,context).active,race==='gem-dragonborn-ftd');d.conditions='';assert.equal(SpeciesForms.state(d,context).active,race==='gem-dragonborn-ftd');F.resetClassResources(d,'long',{level:5});assert.equal(SpeciesForms.state(d,context).active,false);assert.equal(SpeciesForms.state(d,context).resource.used,0);}
 const {d,context}=speciesForm('dragonborn-2024');SpeciesForms.activate(d,context);d.hpCurrent=0;SpeciesForms.onZeroHP(d);d.hpCurrent=10;assert.equal(SpeciesForms.state(d,context).rawActive,false);assert.equal(SpeciesForms.state(d,context).resource.used,1);
});
test('Chromatic Warding stays bound to its selected ancestry, source and level instead of changing immunity for free',()=>{
 const {d,context}=speciesForm('chromatic-dragonborn-ftd');assert.equal(SpeciesForms.activate(d,context),true);assert.deepEqual(M.derive(d,5).effects.immunities,['Fire damage']);d.build.raceFeature='blue';assert.deepEqual(M.derive(d,5).effects.immunities,[]);SpeciesForms.endInvalid(d,context);d.build.raceFeature='red';assert.deepEqual(M.derive(d,5).effects.immunities,[]);assert.equal(SpeciesForms.state(d,context).resource.remaining,0);assert.equal(SpeciesForms.activate(d,context),false);
 SpeciesForms.undo(d,context);d.build.raceFeature='constructor';assert.equal(SpeciesForms.activate(d,context),false);d.build.raceFeature='red';SpeciesForms.activate(d,context);d.build.race='human';SpeciesForms.endInvalid(d,context);d.build.race='chromatic-dragonborn-ftd';assert.equal(SpeciesForms.state(d,context).active,false);
});
test('species activation rejects dead/incapacitated characters but respects actual legacy Zealot Rage Beyond Death, and malformed flags grant nothing',()=>{
 const {d,context}=speciesForm('gem-dragonborn-ftd');for(const condition of ['Dead','Stunned','Unconscious','Exhaustion 6']){d.conditions=condition;assert.equal(SpeciesForms.activate(d,context),false);}d.conditions='';d.hpCurrent=0;assert.equal(SpeciesForms.activate(d,context),false);d.build.classId='barbarian';d.adobe={classLevels:[{classId:'barbarian',level:14,subclassId:'zealot'}],classFeatureChoices:{'2014:barbarian:rage-state':['zealot']}};d.deathFailure=3;assert.equal(SpeciesForms.activate(d,{...context,level:14}),true);d.adobe.classFeatureChoices['species:gem-dragonborn-ftd:flight-active']=['active','extra'];assert.equal(M.derive(d,14).speciesForm.active,false);
});
