test('alternative feat packages grant only the chosen source and Scion resistance remains tied to its cantrip',()=>{
 const {d,id}=withFeat('Scion of the Outer Planes','SatO',{castingAbility:'wis'});assert.equal(Access.spells(d,4,M.derive(d,4)).length,0);const packages=Feats.mechanicFacts(Feats.definitions[id]).spellPackages;assert.equal(packages.length,5);
 for(let index=0;index<packages.length;index++){d.rulesChoices.effects[id].spellPackage=index;const r=M.derive(d,4),grants=Access.spells(d,4,r);assert.equal(grants.length,1);assert.ok(r.effects.resistances.includes(packages[index].resistance[0].toUpperCase()+packages[index].resistance.slice(1)));assert.equal(r.effects.resistances.filter(x=>['Poison','Necrotic','Radiant','Force','Psychic'].includes(x)).length,1);assert.equal(grants[0].spell.name.toLowerCase(),packages[index].grants[0].ref.split('#')[0]);assert.equal(grants[0].ability,'wis');}
 d.rulesChoices.effects[id].spellPackage=99;assert.equal(Access.spells(d,4,M.derive(d,4)).length,0);assert.equal(M.derive(d,4).effects.resistances.length,0);
});
test('college, moon and Spell Sniper packages cannot union their spell lists and invalid duplicate selections remain inactive',()=>{
 for(const [name,source,expected]of [['Strixhaven Initiate','SCC',3],['Initiate of High Sorcery','DSotDQ',3],['Spell Sniper','PHB',1]]){
  const {d,id}=withFeat(name,source,{spellPackage:name==='Spell Sniper'?5:0,castingAbility:'cha'}),def=Feats.definitions[id],groups=Feats.spellChoices(def,d.rulesChoices.effects[id]);for(const group of groups)for(let n=0;n<group.count;n++)d.rulesChoices.effects[id].spellIds[group.start+n]=group.options[n].id;
  let grants=Access.spells(d,4,M.derive(d,4));assert.equal(grants.length,expected,name);const count=grants.filter(row=>row.spell.level>0).length;assert.equal(M.derive(d,4).classResources.filter(row=>row.id.startsWith('feat-spell-')).length,count,name);
  d.rulesChoices.effects[id].spellPackage=1;grants=Access.spells(d,4,M.derive(d,4));const selected=Feats.spellPackage(def,d.rulesChoices.effects[id]);assert.ok(grants.length<=expected);for(const grant of grants)assert.ok(selected.grants.some(g=>g.ref.split(/[|#]/)[0]===grant.spell.name.toLowerCase())||Feats.spellChoices(def,d.rulesChoices.effects[id]).some(g=>g.options.some(s=>s.id===grant.spell.id)),name);
 }
 const high=withFeat('Initiate of High Sorcery','DSotDQ',{spellPackage:0,castingAbility:'int'}),groups=Feats.spellChoices(Feats.definitions[high.id],high.d.rulesChoices.effects[high.id]),two=groups.find(g=>g.count===2);high.d.rulesChoices.effects[high.id].spellIds[two.start]=two.options[0].id;high.d.rulesChoices.effects[high.id].spellIds[two.start+1]=two.options[0].id;assert.equal(Access.spells(high.d,4,M.derive(high.d,4)).filter(g=>g.spell.level>0).length,0);
});
test('Siberys chooses one spell, accepts suggested marks without owning that mark, and recovers only on its declared rests',()=>{
 const {d,id}=withFeat('Boon of Siberys','EFA',{spellPackage:0,castingAbility:'wis',abilities:['wis']});d.adobe={classLevels:[{classId:'fighter',level:19}]};assert.equal(Access.spells(d,18,M.derive(d,18)).length,0);let r=M.derive(d,19);assert.deepEqual(Access.spells(d,19,r).map(g=>g.spell.name),['Animal Shapes']);let pool=r.classResources.find(g=>g.id.startsWith('feat-spell-'));assert.deepEqual(pool.resets,['short','long']);assert.equal(F.changeClassResource(d,pool.id,1,{level:19}),true);F.resetClassResources(d,'turn',{level:19});assert.equal(M.derive(d,19).classResources.find(g=>g.id===pool.id).remaining,0);F.resetClassResources(d,'short',{level:19});assert.equal(M.derive(d,19).classResources.find(g=>g.id===pool.id).remaining,1);
 d.rulesChoices.effects[id].spellPackage=12;const options=Feats.spellChoices(Feats.definitions[id],d.rulesChoices.effects[id])[0];assert.ok(options.options.some(s=>s.level===0));d.rulesChoices.effects[id].spellIds[0]=options.options.find(s=>s.name==='Fire Bolt').id;assert.deepEqual(Access.spells(d,19,M.derive(d,19)).map(g=>g.spell.name),['Fire Bolt']);
});
test('replacement cantrips require the explicit known-cantrip confirmation and Magic Connoisseur matches actual Magic Initiate list/ability',()=>{
 const cold=withFeat('Cold Caster','FRHoF',{spellPackage:1,abilities:['wis']}),group=Feats.spellChoices(Feats.definitions[cold.id],cold.d.rulesChoices.effects[cold.id])[0];cold.d.rulesChoices.effects[cold.id].spellIds[0]=group.options.find(s=>s.name==='Light').id;assert.equal(Access.spells(cold.d,4,M.derive(cold.d,4)).length,0);cold.d.rulesChoices.effects[cold.id].confirmed=true;assert.deepEqual(Access.spells(cold.d,4,M.derive(cold.d,4)).map(g=>g.spell.name),['Light']);assert.equal(Access.spells(cold.d,4,M.derive(cold.d,4))[0].ability,'wis');
 const mc=withFeat('Magic Connoisseur','AU',{spellPackage:2,abilities:['int']});for(const group of Feats.spellChoices(Feats.definitions[mc.id],mc.d.rulesChoices.effects[mc.id]))mc.d.rulesChoices.effects[mc.id].spellIds[group.start]=group.options[0].id;assert.equal(Access.spells(mc.d,4,M.derive(mc.d,4)).length,0);mc.d.build.race='human-2024';mc.d.build.humanOriginFeat='Magic Initiate (Wizard)';mc.d.rulesChoices.grants.human={classId:'wizard',ability:'wis',spells:['Fire Bolt','Light','Magic Missile'].map(name=>Catalog.data.spells.find(s=>s.name===name&&s.edition==='2024').id),used:0};const grants=Access.spells(mc.d,4,M.derive(mc.d,4)).filter(g=>g.source.includes('Connoisseur'));assert.equal(grants.length,2);assert.ok(grants.every(g=>g.ability==='wis'));mc.d.rulesChoices.effects[mc.id].spellPackage=0;assert.equal(Access.spells(mc.d,4,M.derive(mc.d,4)).filter(g=>g.source.includes('Connoisseur')).length,0);
});
test('all dragonmark expanded lists extend actual class choices without free preparation, extra slots or shared-slot reach',()=>{
 const {d,id}=withFeat('Mark of Handling','EFA',{castingAbility:'wis'});d.build.classId='wizard';d.adobe={classLevels:[{classId:'wizard',level:1},{classId:'sorcerer',level:4}]};const before=JSON.stringify(d),derived=M.derive(d,5),profiles=Casting.profiles(d,5,derived.scores),wizard=profiles.find(p=>p.classId==='wizard'),sorcerer=profiles.find(p=>p.classId==='sorcerer');const command=Catalog.data.spells.find(s=>s.name==='Command'&&s.edition==='2024'),beast=Catalog.data.spells.find(s=>s.name==='Beast Sense'&&s.edition==='2024');assert.ok(Casting.eligibleSpells(wizard,Catalog.data.spells).some(s=>s.id===command.id));assert.ok(!Casting.eligibleSpells(wizard,Catalog.data.spells).some(s=>s.id===beast.id));assert.ok(Casting.eligibleSpells(sorcerer,Catalog.data.spells).some(s=>s.id===beast.id));assert.ok(!Casting.automaticGrants(wizard,Catalog.data.spells).some(s=>s.id===command.id));assert.equal(JSON.stringify(d),before);
 d.spells=[{...Catalog.spellRow(command),classId:'wizard'}];d.actions=[{kind:'spell',ref:command.id+'::wizard'}];assert.equal(M.derive(d,5).actions[0].available,true);assert.equal(Access.spells(d,5,M.derive(d,5)).find(s=>s.ref===command.id+'::wizard').ability,'int');d.rulesChoices.feats=[];assert.equal(Access.spells(d,5,M.derive(d,5)).some(s=>s.ref===command.id+'::wizard'),false);assert.equal(d.spells.length,1);
 d.rulesChoices.feats=[id];d.build.classId='barbarian';d.adobe.classLevels=[{classId:'barbarian',level:5}];assert.equal(Casting.profiles(d,5,derived.scores).filter(p=>p.mode!=='innate').length,0);
 for(const [key,facts]of Object.entries(FeatFacts.records).filter(([,facts])=>facts.expandedSpells?.length)){const [source,name]=key.split('|'),sample=withFeat(name,source,{castingAbility:'wis'},{classId:'wizard'});const expanded=Feats.expandedSpells(sample.d,{level:20});assert.equal(expanded.length,facts.expandedSpells.reduce((n,row)=>n+row.spells.length,0),name);assert.ok(expanded.every(s=>s.edition==='2024'));sample.d.build.edition='2014';assert.equal(Feats.expandedSpells(sample.d,{level:20}).length,0);}
});
test('standalone sheets retain racial and feat free-cast spending before an explicit multiclass allocation exists',()=>{
 const {d}=withFeat('Fey Touched','TCE',{abilities:['wis']});d.build.race='drow';assert.equal(d.adobe,undefined);const rows=M.derive(d,5).classResources.filter(r=>r.id.startsWith('origin-')||r.id.startsWith('feat-spell-'));assert.ok(rows.length>=3);for(const row of rows)assert.equal(F.changeClassResource(d,row.id,1,{level:5}),true);const spent=M.derive(d,5).classResources.filter(r=>rows.some(before=>before.id===r.id));assert.ok(spent.every(r=>r.remaining===0));const saved=JSON.parse(JSON.stringify(d));assert.ok(M.derive(saved,5).classResources.filter(r=>rows.some(before=>before.id===r.id)).every(r=>r.remaining===0));F.resetClassResources(saved,'long',{level:5});assert.ok(M.derive(saved,5).classResources.filter(r=>rows.some(before=>before.id===r.id)).every(r=>r.remaining===1));assert.equal(saved.adobe.classLevels,undefined);
});
