test('reviewed spell damage overrides preserve every numeric/type fact and never copy source entries',()=>{
 const overrides=require('../scripts/spell-combat-overrides.json');assert.equal(overrides.revision,Catalog.rawData.indexRevision);let count=0;
 for(const spell of Catalog.rawData.spells){const rule=overrides.spells[spell.name];if(!rule)continue;const fields={...rule.default,...rule.bySource?.[spell.source]};for(const [key,value]of Object.entries(fields))if(value===null)assert.equal(Object.hasOwn(spell.combat,key),false,spell.name+' '+key);else assert.deepEqual(spell.combat[key],value,spell.name+' '+key);count++;}
 assert.ok(count>=40);assert.doesNotMatch(JSON.stringify(overrides),/\{@|"entries"/);
});
test('new direct damage references scale slot dice while projectile counts and per-target damage remain distinct',()=>{
 const cases=[['Catapult','2014',3,'5d8 bludgeoning'],['Arms of Hadar','2024',3,'4d6 necrotic'],["Snilloc's Snowball Swarm",'2014',4,'5d6 cold'],['Frost Fingers','2014',3,'4d8 cold'],['Negative Energy Flood','2024',7,'5d10 + 25 necrotic'],['Negative Energy Flood','2014',7,'5d12 necrotic'],["Melf's Minute Meteors",'2014',5,'2d6 fire'],['Crown of Stars','2014',9,'4d12 radiant'],["Tasha's Mind Whip",'2014',4,'3d6 psychic'],['Steel Wind Strike','2024',5,'6d10 force']];
 for(const [name,edition,slot,damage]of cases){const d=character({edition,classId:'wizard'}),spell=Catalog.rawData.spells.find(s=>s.name===name&&s.edition===edition);assert.ok(spell,name);d.spells=[{...Catalog.spellRow(spell),classId:'additional'}];d.actions=[{kind:'spell',ref:spell.id+'::additional',slot}];const r=M.derive(d,20).actions[0];assert.equal(r.damage,damage,name);assert.ok(!r.notes.includes('Upcast effects are not automated for this spell.'),name);if(name==='Crown of Stars')assert.match(r.notes.join(' '),/Creates 11 motes/);if(name==="Melf's Minute Meteors")assert.match(r.notes.join(' '),/Creates 10 meteors/);if(name==='Negative Energy Flood')assert.match(r.notes.join(' '),/Undead/);}
});
