test('type-dependent spell bonuses reach the matching damage component and wait for unresolved type choices',()=>{
 const d=dragon('cold'),knife=Catalog.rawData.spells.find(s=>s.name==='Ice Knife'&&s.edition==='2014');d.spells=[{...Catalog.spellRow(knife),classId:'sorcerer'}];d.actions=[{kind:'spell',ref:knife.id+'::sorcerer',slot:3}];let r=M.derive(d,6).actions[0];assert.match(r.damage,/^1d10 piercing; explosion 4d6 \+ 4 cold/);assert.equal(r.damageDice,'1d10; 4d6+4');
 F.set(d,d.adobe.classLevels[0],'dragon-element',0,'fire');r=M.derive(d,6).actions[0];assert.doesNotMatch(r.damage,/\+ 4/);const orb=Catalog.rawData.spells.find(s=>s.name==='Chromatic Orb'&&s.edition==='2014');d.spells=[{...Catalog.spellRow(orb),classId:'sorcerer'}];d.actions=[{kind:'spell',ref:orb.id+'::sorcerer'}];r=M.derive(d,6).actions[0];assert.doesNotMatch(r.damage,/\+ 4/);assert.match(r.notes.join(' '),/type-dependent bonuses only after/);
 const racial=dragon('cold',{edition:'2024',race:'rimekin-lfl'}),grant=Access.spells(racial,6,M.derive(racial,6)).find(g=>g.ref.endsWith('::race')&&g.spell.name==='Flame Blade');assert.ok(grant);racial.actions=[{kind:'granted-spell',ref:grant.ref}];assert.equal(M.derive(racial,6).actions[0].damage,'3d6 + 3 + 4 cold');F.set(racial,racial.adobe.classLevels[0],'dragon-element',0,'fire');assert.equal(M.derive(racial,6).actions[0].damage,'3d6 + 3 cold');
});
