 const d=character({classId:'wizard'}),storm=Catalog.rawData.spells.find(s=>s.name==='Ice Storm'&&s.edition==='2014');d.adobe={classLevels:[{classId:'wizard',level:10,subclassId:'evocation'}]};d.spells=[{...Catalog.spellRow(storm),classId:'wizard'}];d.actions=[{kind:'spell',ref:storm.id+'::wizard'}];const r=M.derive(d,10).actions[0];assert.equal(r.damage,'2d8 bludgeoning + 4d6 cold +3 once');assert.match(r.notes.join(' '),/one eligible damage component/);
 const mixed=dragon('fire',{edition:'2024'}),warlock={classId:'warlock',level:3,subclassId:'great-old-one-patron-2024'},bolt=Catalog.rawData.spells.find(s=>s.name==='Fire Bolt'&&s.edition==='2024');mixed.adobe.classLevels.push(warlock);M.derive(mixed,9);assert.equal(F.set(mixed,warlock,'eldritch-invocations',0,'pact-of-the-tome'),true);mixed.spells=[{...Catalog.spellRow(bolt),classId:'warlock'}];mixed.actions=[{kind:'spell',ref:bolt.id+'::warlock'}];assert.equal(M.derive(mixed,9).actions[0].damage,'2d10 + 4 fire');assert.ok(require('../js/modules/character-warlock-subclasses').use(mixed,'psychic-spells',{level:9,mods:M.derive(mixed,9).mods}));assert.equal(M.derive(mixed,9).actions[0].damage,'2d10 psychic');
