function mistyActor(){const {d,id}=withFeat('Boon of Misty Escape','ABH',{abilities:['wis']});d.hpMax=40;d.hpCurrent=0;d.adobe={classLevels:[{classId:'fighter',level:19}],classFeatureChoices:{'manual:kept':['3']}};return{d,id};}
test('Misty Escape requires its exact feat, level, nonfatal trigger confirmation, 0 HP, live character and spellcasting conditions',()=>{
 const {d,id}=mistyActor(),before=JSON.stringify(d);assert.equal(Forms.activate(d,{level:19}),false);assert.equal(JSON.stringify(d),before);assert.equal(Forms.activate(d,{level:18,confirmed:true}),false);d.hpCurrent=2;assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);d.hpCurrent=0;d.deathFailure=3;assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);d.deathFailure=0;
 for(const condition of ['Unconscious','Incapacitated','Paralyzed','Stunned','Petrified','Dead','Exhaustion 6']){d.conditions=condition;assert.equal(Forms.activate(d,{level:19,confirmed:true}),false,condition);}d.conditions='';d.adobe.classLevels=[{classId:'barbarian',level:1},{classId:'fighter',level:18}];d.adobe.classFeatureChoices['2024:barbarian:rage-state']=['base'];assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);delete d.adobe.classFeatureChoices['2024:barbarian:rage-state'];d.rulesChoices.feats=[];assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);d.rulesChoices.feats=[id];d.rulesChoices.effects[id].abilities=['str'];assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);
});
test('Misty Escape atomically spends one use, keeps 1 HP, clears death-save records and supplies only active self-form defenses/movement',()=>{
 const {d}=mistyActor();d.deathSuccess=2;d.deathFailure=1;const kept=JSON.stringify({slots:d.slots,coins:d.coins,attacks:d.attacks,inventory:d.personalGear}),base=M.derive(d,19),row=base.classResources.find(r=>r.name==='Misty Escape');assert.ok(row);assert.equal(row.managedActivation,true);assert.equal(F.changeClassResource(d,row.id,1,{level:19}),false);assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);assert.equal(d.hpCurrent,1);assert.equal(d.deathSuccess,0);assert.equal(d.deathFailure,0);const before=JSON.stringify(d),after=M.derive(d,19);assert.equal(after.featForm.active,true);assert.deepEqual(after.movement.speeds,{speed:0,climb:0,swim:0,burrow:0,fly:20});assert.equal(after.effects.hover,true);for(const type of ['Bludgeoning','Piercing','Slashing'])assert.ok(after.effects.resistances.includes(type));assert.ok(after.effects.immunities.includes('Prone'));assert.deepEqual(after.effects.saveAdvantages,['str','dex','con']);assert.deepEqual(after.saves,base.saves);assert.equal(JSON.stringify(d),before,'projection never spends, heals or advances time');assert.equal(F.changeClassResource(d,row.id,-1,{level:19}),false,'generic undo cannot refund an activation');assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);assert.equal(JSON.stringify({slots:d.slots,coins:d.coins,attacks:d.attacks,inventory:d.personalGear}),kept);assert.equal(d.adobe.classFeatureChoices['manual:kept'][0],'3');
 Forms.end(d);const ended=M.derive(d,19);assert.equal(ended.featForm.active,false);assert.deepEqual(ended.effects.resistances,base.effects.resistances);assert.equal(ended.effects.speed,base.effects.speed);assert.equal(ended.classResources.find(r=>r.name==='Misty Escape').remaining,0);assert.equal(d.hpCurrent,1);
});
test('Misty Escape cannot be used as an ordinary Gaseous Form grant and blocks derived, manual and paper attacks/spells while active',()=>{
 const {d}=mistyActor(),s=Catalog.data.spells.find(s=>s.name==='Fire Bolt'&&s.edition==='2024');d.spells=[{...Catalog.spellRow(s),classId:'additional'}];d.actions=[{kind:'unarmed'},{kind:'spell',ref:s.id+'::additional'}];d.attacks=[{id:'manual-mist',name:'Manual attack',ability:'dex',proficient:true,bonus:0}];let r=M.derive(d,19);assert.ok(!Access.spells(d,19,r).some(g=>g.spell.name==='Gaseous Form'));assert.equal(Feats.spellGrants(d,{level:19})[0].referenceOnly,true);assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);r=M.derive(d,19);assert.ok(r.actions.every(a=>a.available===false));d.adobe.proficiencyDice=true;const dice=M.derive(d,19);assert.ok(dice.actions.every(a=>a.available===false&&a.hit==='—'));assert.ok(dice.manualAttacks.every(a=>a.attack===null));const A=require('../js/modules/character-paper-attacks');assert.ok(A.candidates(d,r).every(row=>row.available===false&&row.unavailable&&row.hit==='—'));Forms.end(d);assert.ok(M.derive(d,19).actions.every(a=>a.available===true));
});
test('Misty Escape regeneration follows explicit own turns, caps at current maximum HP, never revives at 0 and ends on rest without refunding early',()=>{
 const {d}=mistyActor();assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);F.resetClassResources(d,'turn',{level:19});assert.equal(d.hpCurrent,11);d.hpCurrent=37;F.resetClassResources(d,'turn',{level:19});assert.equal(d.hpCurrent,40);d.hpCurrent=45;F.resetClassResources(d,'turn',{level:19});assert.equal(d.hpCurrent,45,'regeneration never reduces HP already above a changed maximum');F.resetClassResources(d,'short',{level:19});assert.equal(Forms.state(d,{level:19}).active,true,'shortened rests do not imply a full hour passed; duration ends explicitly');assert.equal(M.derive(d,19).classResources.find(r=>r.name==='Misty Escape').remaining,0);F.resetClassResources(d,'long',{level:19});assert.equal(M.derive(d,19).classResources.find(r=>r.name==='Misty Escape').remaining,1);d.hpCurrent=0;assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);d.hpCurrent=0;F.resetClassResources(d,'turn',{level:19});assert.equal(d.hpCurrent,0);assert.equal(Forms.state(d,{level:19}).rawActive,false);d.hpCurrent=10;assert.equal(Forms.state(d,{level:19}).active,false);
});
test('Misty Escape maintains existing movement penalties and ends when concentration becomes impossible, Rage begins or the feat is removed',()=>{
 const {d,id}=mistyActor();assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);d.conditions='Exhaustion 1';assert.equal(M.derive(d,19).effects.fly,15);d.conditions='Grappled';assert.equal(M.derive(d,19).effects.fly,0);d.conditions='Paralyzed';assert.equal(Forms.state(d,{level:19}).active,false);Forms.endInvalid(d,{level:19});d.conditions='';assert.equal(Forms.state(d,{level:19}).active,false);F.resetClassResources(d,'long',{level:19});d.hpCurrent=0;assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);d.adobe.classLevels=[{classId:'barbarian',level:1},{classId:'fighter',level:18}];assert.equal(require('../js/modules/character-barbarian-subclasses').enterRage(d,{level:19}),true);assert.equal(Forms.state(d,{level:19}).rawActive,false);require('../js/modules/character-barbarian-subclasses').endRage(d,{level:19});assert.equal(Forms.state(d,{level:19}).active,false);F.resetClassResources(d,'long',{level:19});d.hpCurrent=0;assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);Feats.remove(d,id);assert.equal(Forms.state(d,{level:19}).active,false);d.rulesChoices.feats=[id];d.rulesChoices.effects[id]=Feats.choice({abilities:['wis']});assert.equal(Forms.state(d,{level:19}).rawActive,false);
});
test('Misty Escape capacity failures are atomic and malformed ledgers fail closed until an explicit Long Rest, including while deselected',()=>{
 const {d,id}=mistyActor();d.adobe.classFeatureChoices=Object.fromEntries(Array.from({length:99},(_,i)=>['kept:'+i,['0']]));const before=JSON.stringify(d);assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);assert.equal(JSON.stringify(d),before);d.adobe.classFeatureChoices={};let state=Forms.state(d,{level:19});d.adobe.classFeatureChoices[state.usedKey]=['unknown'];assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);assert.equal(M.derive(d,19).classResources.find(r=>r.name==='Misty Escape').remaining,0);for(const malformed of [null,'0',{},['0','1']]){d.adobe.classFeatureChoices[state.usedKey]=malformed;assert.equal(Forms.activate(d,{level:19,confirmed:true}),false);assert.equal(M.derive(d,19).classResources.find(r=>r.name==='Misty Escape').remaining,0);}d.rulesChoices.feats=[];F.resetClassResources(d,'long',{level:19});d.rulesChoices.feats=[id];assert.equal(Forms.state(d,{level:19}).used,0);assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);const copy=M.normalize(JSON.parse(JSON.stringify(d)));copy.adobe=d.adobe;assert.equal(Forms.state(copy,{level:19}).active,true);
});

test('Misty Escape blocks free-spell spending while transformed but allows ledger corrections and restores access after ending',()=>{
 const {d}=mistyActor(),fey=featId('Fey-Touched','XPHB');d.rulesChoices.feats.push(fey);d.rulesChoices.effects[fey]=Feats.choice({abilities:['wis']});assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);let row=M.derive(d,19).classResources.find(r=>r.name.includes('Misty Step'));assert.ok(row);assert.equal(row.useDisabled,true);assert.equal(F.changeClassResource(d,row.id,1,{level:19}),false);Forms.end(d);row=M.derive(d,19).classResources.find(r=>r.id===row.id);assert.equal(row.useDisabled,false);assert.equal(F.changeClassResource(d,row.id,1,{level:19}),true);
});

test('removing an ineligible duplicate feat cannot end the original active Misty Escape',()=>{
 const {d,id}=mistyActor();assert.equal(Forms.activate(d,{level:19,confirmed:true}),true);d.rulesChoices.feats.push(id);d.rulesChoices.effects[id+'--2']=Feats.choice({abilities:['wis']});assert.equal(M.derive(d,19).feats.reports.length,1,'normalized projection ignores a nonrepeatable duplicate');Feats.remove(d,id+'--2');assert.equal(Forms.state(d,{level:19}).active,true);assert.equal(Forms.state(d,{level:19}).used,1);
});
